def solve_sudoku(grid):
    def is_valid(grid, r, c, k):
        for i in range(9):
            if grid[r][i] == k: return False
            if grid[i][c] == k: return False
            if grid[3 * (r // 3) + i // 3][3 * (c // 3) + i % 3] == k: return False
        return True

    def solve(grid):
        for r in range(9):
            for c in range(9):
                if grid[r][c] == 0:
                    for k in range(1, 10):
                        if is_valid(grid, r, c, k):
                            grid[r][c] = k
                            if solve(grid):
                                return True
                            grid[r][c] = 0
                    return False
        return True

    if solve(grid):
        return grid
    else:
        return None

grid = [[0]*9 for _ in range(9)]
givens = {2: 3, 11: 6, 13: 8, 20: 9, 22: 2, 35: 7, 42: 2, 46: 9, 50: 4, 57: 6, 58: 4, 60: 9, 62: 8, 69: 5, 78: 6, 79: 4}
for k, v in givens.items():
    grid[k // 9][k % 9] = v

res = solve_sudoku(grid)
if res:
    print([x for row in res for x in row])
else:
    print("UNSAT")
